/**
 * Kubernetes resource quantities, read the way the API server reads them
 * (k8s.io/apimachinery resource.Quantity) and checked for the mistakes the
 * docs warn about: https://kubernetes.io/docs/concepts/configuration/manage-resources-containers/
 */

export type ResourceKind = "cpu" | "memory"
export type ResourceSide = "request" | "limit"
export interface ResourcePair {
  request: string
  limit: string
}
export interface K8sResources {
  cpu: ResourcePair
  memory: ResourcePair
}
export type FieldKey = `${ResourceKind}.${ResourceSide}`
export interface NodeCapacity {
  /** Allocatable CPU on the largest node, as a quantity ("4", "3920m"). */
  cpu?: string
  /** Allocatable memory on the largest node ("16Gi", "15843Mi"). */
  memory?: string
}

export type ResourceIssueKind =
  | "invalid"
  | "unit-typo"
  | "cpu-memory-unit"
  | "cpu-whole-cores"
  | "cpu-precision"
  | "memory-millibytes"
  | "memory-bytes"
  | "limit-below-request"
  | "limit-below-request-units"
  | "too-big-for-node"
  | "limit-copies-request"
  | "no-memory-limit"
export interface ResourceFix {
  /** What the button does, for its label: use a value, swap two fields, raise the limit or lower the request. */
  action: "use" | "swap" | "raise-limit" | "lower-request"
  /** The value the button puts in. */
  label: string
  /** Field values to set. */
  set: Partial<Record<FieldKey, string>>
}
export interface ResourceIssue {
  kind: ResourceIssueKind
  severity: "error" | "warning" | "info"
  field: FieldKey
  /** Values filled into the message template. */
  detail: Record<string, string>
  fixes: ResourceFix[]
}

const BINARY: Record<string, number> = { Ki: 2 ** 10, Mi: 2 ** 20, Gi: 2 ** 30, Ti: 2 ** 40, Pi: 2 ** 50, Ei: 2 ** 60 }
const DECIMAL: Record<string, number> = { n: 1e-9, u: 1e-6, m: 1e-3, "": 1, k: 1e3, M: 1e6, G: 1e9, T: 1e12, P: 1e15, E: 1e18 }
const QUANTITY = /^([+-]?(?:\d+(?:\.\d*)?|\.\d+))(?:([eE][+-]?\d+)|(Ki|Mi|Gi|Ti|Pi|Ei|n|u|m|k|M|G|T|P|E))?$/

export interface Quantity {
  /** Value in base units: cores for CPU, bytes for memory. */
  value: number
  number: string
  suffix: string
}

/** Strips the clutter a pasted value brings along: quotes, `cpu:` keys, spaces, CR and BOM. */
export function cleanQuantity(raw: string): string {
  return String(raw ?? "")
    .replace(/^\uFEFF/, "")
    .replace(/^\s*(?:cpu|memory)\s*:\s*/i, "")
    .trim()
    .replace(/^(["'])(.*)\1$/, "$2")
    .trim()
}

/** Parses one quantity with the API server's grammar (suffixes n u m "" k M G T P E, Ki…Ei, or e/E exponents), or returns null when it would reject it. */
export function parseQuantity(raw: string): Quantity | null {
  const text = cleanQuantity(raw)
  const match = QUANTITY.exec(text)
  if (!match) return null
  const [, number, exponent, suffix = ""] = match
  const base = Number(number)
  const value = exponent ? base * 10 ** Number(exponent.slice(1)) : base * (BINARY[suffix] ?? DECIMAL[suffix])
  if (!Number.isFinite(value) || value < 0) return null
  return { value, number, suffix: exponent ?? suffix }
}

/** Guesses what an unparseable quantity meant: 512MB → 512Mi, 1g → 1Gi, 2 GB → 2Gi, 0.5 cores → 500m. */
export function suggestUnit(raw: string, kind: ResourceKind): string[] {
  const text = cleanQuantity(raw).replace(/\s+/g, "")
  const match = /^(\d+(?:\.\d+)?)([a-zA-Z]+)$/.exec(text)
  if (!match) return []
  const [, number, unit] = match
  if (kind === "cpu") {
    if (/^(cores?|cpus?|vcpus?)$/i.test(unit)) return [toMilli(Number(number))]
    if (/^(mc|millicores?|millicpus?)$/i.test(unit)) return [`${number}m`]
    return []
  }
  const letter = unit[0].toUpperCase()
  if (!"KMGTPE".includes(letter) || !/^[kKmMgGtTpPeE](i?[bB]?|[bB]|iB)$/.test(unit)) return []
  const binary = `${number}${letter}i`
  const decimal = `${number}${letter === "K" ? "k" : letter}`
  return /i/.test(unit) || unit.length === 1 ? [binary] : [binary, decimal]
}

function toMilli(cores: number) {
  const milli = Math.round(cores * 1000)
  return milli % 1000 === 0 ? String(milli / 1000) : `${milli}m`
}

/** Reads a CPU amount back in words: 0.5 → "half a core", 250m → "a quarter of a core", 2 → "2 cores". */
export function describeCpu(cores: number): string {
  if (cores === 0) return "no CPU"
  const named: Record<number, string> = { 0.25: "a quarter of a core", 0.5: "half a core", 0.75: "three quarters of a core", 1: "1 core" }
  if (named[cores]) return named[cores]
  if (cores < 1) return `${trim(cores * 100, 1)}% of a core`
  return `${trim(cores, 3)} cores`
}

/** Reads a memory amount back in both systems: 512Mi → "512 MiB · 537 MB". */
export function describeMemory(bytes: number): string {
  if (bytes < 1024) return `${trim(bytes, 3)} bytes`
  const units = ["KiB", "MiB", "GiB", "TiB", "PiB"]
  let binary = bytes / 1024
  let index = 0
  while (binary >= 1024 && index < units.length - 1) {
    binary /= 1024
    index++
  }
  const decimalUnits = ["kB", "MB", "GB", "TB", "PB"]
  let decimal = bytes / 1000
  let dIndex = 0
  while (decimal >= 1000 && dIndex < decimalUnits.length - 1) {
    decimal /= 1000
    dIndex++
  }
  return `${trim(binary, 1)} ${units[index]} · ${trim(decimal, 1)} ${decimalUnits[dIndex]}`
}

function trim(value: number, digits: number) {
  return Number(value.toFixed(digits)).toLocaleString("en-US", { maximumFractionDigits: digits })
}

/** Formats a CPU amount in base units back to a quantity string ("1500m", "2"). */
export function formatCpu(cores: number) {
  return toMilli(cores)
}

/** Formats bytes as the largest exact binary quantity ("512Mi", "1536Mi"), falling back to plain bytes. */
export function formatMemory(bytes: number) {
  for (const suffix of ["Ei", "Pi", "Ti", "Gi", "Mi", "Ki"]) {
    const scaled = bytes / BINARY[suffix]
    if (scaled >= 1 && Number.isInteger(scaled)) return `${scaled}${suffix}`
  }
  return String(Math.ceil(bytes))
}

/** Pulls cpu and memory requests and limits out of a pasted `resources:` YAML block (CRLF safe). */
export function parseResourcesYaml(text: string): K8sResources | null {
  if (!/requests\s*:|limits\s*:/.test(text)) return null
  const result: K8sResources = { cpu: { request: "", limit: "" }, memory: { request: "", limit: "" } }
  let side: ResourceSide | null = null
  let found = false
  for (const line of text.replace(/^\uFEFF/, "").split(/\r?\n/)) {
    const content = line.replace(/#.*$/, "").trim()
    // Only the first container's block: a second `resources:` or `- name:` would mix two containers' values.
    if (found && /^(?:-\s*name\s*:|resources\s*:)/.test(content)) break
    if (/^requests\s*:/.test(content)) side = "request"
    else if (/^limits\s*:/.test(content)) side = "limit"
    const pair = /^(?:requests\s*:|limits\s*:)?\s*\{?\s*(.*)$/.exec(content)?.[1] ?? ""
    for (const [, key, value] of pair.matchAll(/(cpu|memory)\s*:\s*("[^"]*"|'[^']*'|[^,}\s]+)/g)) {
      if (!side) continue
      result[key as ResourceKind][side] = cleanQuantity(value)
      found = true
    }
  }
  return found ? result : null
}

const field = (kind: ResourceKind, side: ResourceSide): FieldKey => `${kind}.${side}`

/** Checks one container's requests and limits and returns every mistake, most serious first. */
export function checkResources(resources: K8sResources, node?: NodeCapacity): ResourceIssue[] {
  const issues: ResourceIssue[] = []
  const parsed: Partial<Record<FieldKey, Quantity>> = {}
  const safe = (kind: ResourceKind, side: ResourceSide) => String(resources?.[kind]?.[side] ?? "")
  const nodeCpu = node?.cpu ? parseQuantity(node.cpu) : null

  for (const kind of ["cpu", "memory"] as const) {
    for (const side of ["request", "limit"] as const) {
      const raw = cleanQuantity(safe(kind, side))
      const key = field(kind, side)
      if (!raw) continue
      const quantity = parseQuantity(raw)
      if (!quantity) {
        const guesses = suggestUnit(raw, kind)
        issues.push({
          kind: guesses.length ? "unit-typo" : "invalid",
          severity: "error",
          field: key,
          detail: { value: raw },
          fixes: guesses.map((guess) => ({ action: "use", label: guess, set: { [key]: guess } })),
        })
        continue
      }
      const before = issues.length
      if (kind === "cpu") {
        if (/i$/.test(quantity.suffix) || /^[MGTPE]$/.test(quantity.suffix)) {
          const swap = safe("memory", side)
          issues.push({ kind: "cpu-memory-unit", severity: "error", field: key, detail: { value: raw }, fixes: swap && !parseQuantity(swap)?.suffix.match(/i$|^[MGTPE]$/) ? [{ action: "swap", label: raw, set: { [key]: swap, [field("memory", side)]: raw } }] : [] })
        } else if (quantity.suffix !== "m" && Number.isInteger(quantity.value) && quantity.value >= 50 && !(nodeCpu && quantity.value <= nodeCpu.value)) {
          issues.push({ kind: "cpu-whole-cores", severity: "error", field: key, detail: { value: raw, cores: String(quantity.value), milli: `${quantity.value}m`, meant: describeCpu(quantity.value / 1000) }, fixes: [{ action: "use", label: `${quantity.value}m`, set: { [key]: `${quantity.value}m` } }] })
        } else if (quantity.value > 0 && Math.abs(quantity.value * 1000 - Math.round(quantity.value * 1000)) > 1e-9) {
          const up = formatCpu(Math.max(0.001, Math.ceil(quantity.value * 1000) / 1000))
          issues.push({ kind: "cpu-precision", severity: "warning", field: key, detail: { value: raw, fixed: up }, fixes: [{ action: "use", label: up, set: { [key]: up } }] })
        }
      } else if (/^[mun]$/.test(quantity.suffix) && quantity.value < 2 ** 20) {
        const n = quantity.number
        issues.push({ kind: "memory-millibytes", severity: "error", field: key, detail: { value: raw, bytes: describeMemory(quantity.value), binary: `${n}Mi`, decimal: `${n}M` }, fixes: [{ action: "use", label: `${n}Mi`, set: { [key]: `${n}Mi` } }, { action: "use", label: `${n}M`, set: { [key]: `${n}M` } }] })
      } else if (quantity.value > 0 && quantity.value < 2 ** 20) {
        const n = quantity.number
        const guesses = Number(n) <= 64 ? [`${n}Gi`, `${n}Mi`] : [`${n}Mi`]
        issues.push({ kind: "memory-bytes", severity: "error", field: key, detail: { value: raw, bytes: describeMemory(quantity.value) }, fixes: guesses.map((guess) => ({ action: "use", label: guess, set: { [key]: guess } })) })
      }
      // A value with a unit slip is judged on its own; comparing it with the other side would only repeat the same mistake.
      if (issues.length === before) parsed[key] = quantity
    }

    const request = parsed[field(kind, "request")]
    const limit = parsed[field(kind, "limit")]
    const format = kind === "cpu" ? formatCpu : formatMemory
    if (request && limit && limit.value < request.value - 1e-12) {
      const mixed = kind === "memory" && /i$/.test(request.suffix) !== /i$/.test(limit.suffix) && limit.value / request.value > 0.9
      issues.push({
        kind: mixed ? "limit-below-request-units" : "limit-below-request",
        severity: "error",
        field: field(kind, "limit"),
        detail: { request: cleanQuantity(safe(kind, "request")), limit: cleanQuantity(safe(kind, "limit")), requestRead: kind === "cpu" ? describeCpu(request.value) : describeMemory(request.value), limitRead: kind === "cpu" ? describeCpu(limit.value) : describeMemory(limit.value) },
        fixes: [
          { action: "raise-limit", label: cleanQuantity(safe(kind, "request")), set: { [field(kind, "limit")]: cleanQuantity(safe(kind, "request")) } },
          { action: "lower-request", label: cleanQuantity(safe(kind, "limit")), set: { [field(kind, "request")]: cleanQuantity(safe(kind, "limit")) } },
        ],
      })
    }
    const capacity = node?.[kind] ? parseQuantity(node[kind] as string) : null
    const asked = request ?? limit
    if (capacity && asked && asked.value > capacity.value) {
      issues.push({ kind: "too-big-for-node", severity: "error", field: field(kind, request ? "request" : "limit"), detail: { value: cleanQuantity(safe(kind, request ? "request" : "limit")), node: cleanQuantity(node?.[kind] ?? "") }, fixes: [{ action: "use", label: format(capacity.value), set: { [field(kind, request ? "request" : "limit")]: format(capacity.value) } }] })
    }
    if (limit && !cleanQuantity(safe(kind, "request"))) {
      issues.push({ kind: "limit-copies-request", severity: "info", field: field(kind, "request"), detail: { limit: cleanQuantity(safe(kind, "limit")) }, fixes: [] })
    }
  }
  if (parsed["memory.request"] && !cleanQuantity(safe("memory", "limit"))) {
    issues.push({ kind: "no-memory-limit", severity: "info", field: "memory.limit", detail: {}, fixes: [{ action: "use", label: cleanQuantity(safe("memory", "request")), set: { "memory.limit": cleanQuantity(safe("memory", "request")) } }] })
  }
  const order = { error: 0, warning: 1, info: 2 }
  return issues.sort((a, b) => order[a.severity] - order[b.severity])
}

export type QosClass = "Guaranteed" | "Burstable" | "BestEffort"

/**
 * The Pod QoS class a single-container pod with these resources gets
 * (https://kubernetes.io/docs/concepts/workloads/pods/pod-qos/). A missing
 * request copies the limit, so limits alone can still be Guaranteed.
 */
export function qosClass(resources: K8sResources): QosClass {
  const read = (kind: ResourceKind, side: ResourceSide) => parseQuantity(String(resources?.[kind]?.[side] ?? ""))?.value
  const anySet = (["cpu", "memory"] as const).some((kind) => read(kind, "request") !== undefined || read(kind, "limit") !== undefined)
  if (!anySet) return "BestEffort"
  const guaranteed = (["cpu", "memory"] as const).every((kind) => {
    const limit = read(kind, "limit")
    const request = read(kind, "request") ?? limit
    return limit !== undefined && request !== undefined && Math.abs(limit - request) < 1e-9
  })
  return guaranteed ? "Guaranteed" : "Burstable"
}

"use client"

import * as React from "react"
import { CircleAlert, CircleCheck, Cpu, Info, MemoryStick, TriangleAlert } from "lucide-react"

import { cn } from "@/lib/utils"
import { checkResources, describeCpu, describeMemory, parseQuantity, parseResourcesYaml, qosClass, type FieldKey, type K8sResources, type NodeCapacity, type ResourceIssue, type ResourceKind, type ResourceSide } from "@/registry/default/k8s-resource-input/k8s-quantity"

export { checkResources, cleanQuantity, describeCpu, describeMemory, formatCpu, formatMemory, parseQuantity, parseResourcesYaml, qosClass, suggestUnit, type FieldKey, type K8sResources, type NodeCapacity, type QosClass, type Quantity, type ResourceFix, type ResourceIssue, type ResourceIssueKind, type ResourceKind, type ResourcePair, type ResourceSide } from "@/registry/default/k8s-resource-input/k8s-quantity"

export const K8S_RESOURCE_INPUT_MESSAGES = {
  legend: "Container resources",
  "cpu.request": "CPU request",
  "cpu.limit": "CPU limit",
  "memory.request": "Memory request",
  "memory.limit": "Memory limit",
  cpuPlaceholder: "250m",
  memoryPlaceholder: "256Mi",
  unset: "Not set",
  copied: "Same as the limit",
  pasted: "Filled from the pasted YAML (first container only).",
  clean: "Valid. The scheduler and kubelet will read these as shown.",
  toFix: "{count} to fix",
  toNote: "{count} to note",
  use: "Use {value}",
  swap: "Swap with memory",
  "raise-limit": "Raise limit to {value}",
  "lower-request": "Lower request to {value}",
  Guaranteed: "QoS Guaranteed: requests equal limits, so it's evicted last under node pressure.",
  Burstable: "QoS Burstable: can use more than it requests, and is evicted before Guaranteed pods.",
  BestEffort: "QoS BestEffort: nothing set, so it's the first to be evicted and can use the whole node.",
  invalid: "{field}: Kubernetes can't read “{value}”, so the manifest is rejected.",
  "unit-typo": "{field}: “{value}” isn't a Kubernetes unit, so the manifest is rejected. Units are case-sensitive: Mi, Gi, M, G, k.",
  "cpu-memory-unit": "{field}: “{value}” is a memory size. CPU is in cores (1, 0.5) or millicores (500m).",
  "cpu-whole-cores": "{field}: {value} means {cores} whole cores, not millicores, so the pod waits for a node that big. Did you mean {milli} ({meant})?",
  "cpu-precision": "{field}: Kubernetes doesn't support CPU finer than 1m, so {value} is rounded up to {fixed} when it runs.",
  "memory-millibytes": "{field}: lowercase m, u and n mean milli, micro and nano, so {value} is {bytes} of memory. You probably meant {binary} or {decimal}.",
  "memory-bytes": "{field}: a number with no unit is bytes, so {value} is just {bytes}. Add a unit.",
  "limit-below-request": "{field}: the limit ({limitRead}) is below the request ({requestRead}), so the API rejects the pod.",
  "limit-below-request-units": "{field}: {limit} is less than {request}. G and M are powers of 1000, Gi and Mi of 1024, so this limit ({limitRead}) is below the request ({requestRead}) and the API rejects it.",
  "too-big-for-node": "{field}: {value} is more than your largest node has ({node}), so the pod stays Pending forever.",
  "limit-copies-request": "{field}: not set, so Kubernetes copies the limit ({limit}) and reserves all of it.",
  "no-memory-limit": "{field}: none, so this container can use all the node's memory before anything stops it.",
}
export type K8sResourceInputMessages = typeof K8S_RESOURCE_INPUT_MESSAGES

const EMPTY: K8sResources = { cpu: { request: "", limit: "" }, memory: { request: "", limit: "" } }
const FIELDS: [ResourceKind, ResourceSide][] = [["cpu", "request"], ["cpu", "limit"], ["memory", "request"], ["memory", "limit"]]
const fill = (text: string, values: Record<string, string | number>) => text.replace(/\{(\w+)\}/g, (match, key: string) => String(values[key] ?? match))
const tones = { error: "text-red-700 dark:text-red-400", warning: "text-amber-700 dark:text-amber-400", info: "text-muted-foreground" }
const icons = { error: CircleAlert, warning: TriangleAlert, info: Info }
const fixClass = (error: boolean) =>
  cn(
    "inline-flex min-h-6 items-center rounded-md border px-2 font-medium transition-colors outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50",
    error ? "border-red-500/40 text-red-800 hover:bg-red-500/10 dark:text-red-200" : "border-amber-500/40 text-amber-900 hover:bg-amber-500/10 dark:text-amber-200",
  )

function useSettled(text: string, delay = 900) {
  const [settled, setSettled] = React.useState(text)
  React.useEffect(() => {
    const timer = setTimeout(() => setSettled(text), delay)
    return () => clearTimeout(timer)
  }, [text, delay])
  return settled
}

function normalize(value: K8sResources | undefined | null): K8sResources {
  const pick = (kind: ResourceKind, side: ResourceSide) => String(value?.[kind]?.[side] ?? "")
  return { cpu: { request: pick("cpu", "request"), limit: pick("cpu", "limit") }, memory: { request: pick("memory", "request"), limit: pick("memory", "limit") } }
}

export interface K8sResourceInputProps extends Omit<React.ComponentProps<"fieldset">, "defaultValue" | "onChange"> {
  /** Controlled requests and limits for one container. */
  value?: K8sResources
  /** Initial requests and limits when uncontrolled. */
  defaultValue?: K8sResources
  /** Called with all four values on every edit, fix or YAML paste. */
  onValueChange?: (value: K8sResources) => void
  /** Allocatable CPU and memory of your largest node; requests above it are flagged as never schedulable. */
  node?: NodeCapacity
  /** Every visible string. `{field}`, `{value}` and the other placeholders are filled in. */
  messages?: Partial<K8sResourceInputMessages>
}

/**
 * Requests and limits for a Kubernetes container that read every value back
 * in plain units and catch the unit slips the API either rejects or silently
 * accepts: 500 meaning 500 cores, 400m of memory meaning 0.4 bytes, 512MB,
 * a 1G limit under a 1Gi request, and requests no node can fit. Pasting a
 * `resources:` block fills all four fields.
 */
export function K8sResourceInput({ value, defaultValue = EMPTY, onValueChange, node, messages, className, ...props }: K8sResourceInputProps) {
  const t = { ...K8S_RESOURCE_INPUT_MESSAGES, ...messages }
  const [inner, setInner] = React.useState(() => normalize(defaultValue))
  const current = value ? normalize(value) : inner
  const [pasted, setPasted] = React.useState(false)
  const id = React.useId()
  const inputs = React.useRef<Partial<Record<FieldKey, HTMLInputElement | null>>>({})
  const list = React.useRef<HTMLUListElement>(null)
  const refocus = React.useRef<{ index: number; field: FieldKey } | null>(null)

  const update = (next: K8sResources) => {
    if (!value) setInner(next)
    onValueChange?.(next)
  }
  const setField = (key: FieldKey, text: string) => {
    const [kind, side] = key.split(".") as [ResourceKind, ResourceSide]
    setPasted(false)
    update({ ...current, [kind]: { ...current[kind], [side]: text } })
  }

  const issues = React.useMemo(() => checkResources(current, node), [current, node])
  const errors = issues.filter((issue) => issue.severity === "error").length
  const anything = FIELDS.some(([kind, side]) => current[kind][side].trim())
  const summary = !anything ? "" : errors ? [errors && fill(t.toFix, { count: errors }), issues.length - errors && fill(t.toNote, { count: issues.length - errors })].filter(Boolean).join(" · ") : t.clean
  const announced = useSettled(summary)
  const qos = qosClass(current)
  const flagged = new Set(issues.filter((issue) => issue.severity === "error").map((issue) => issue.field))

  // A fix removes its own button, so focus moves to the next fix, or back to the field it changed.
  React.useEffect(() => {
    if (!refocus.current) return
    const buttons = list.current?.querySelectorAll<HTMLButtonElement>("button[data-fix]") ?? []
    ;(buttons[Math.min(refocus.current.index, buttons.length - 1)] ?? inputs.current[refocus.current.field])?.focus()
    refocus.current = null
  })
  const applyFix = (issue: ResourceIssue, set: Partial<Record<FieldKey, string>>, button: HTMLElement) => {
    refocus.current = { index: [...(list.current?.querySelectorAll("button[data-fix]") ?? [])].indexOf(button), field: issue.field }
    const next = normalize(current)
    for (const [key, text] of Object.entries(set)) {
      const [kind, side] = key.split(".") as [ResourceKind, ResourceSide]
      next[kind][side] = text ?? ""
    }
    setPasted(false)
    update(next)
  }

  const readback = (kind: ResourceKind, side: ResourceSide) => {
    const raw = current[kind][side]
    if (!raw.trim()) return side === "request" && current[kind].limit.trim() ? t.copied : t.unset
    const quantity = parseQuantity(raw)
    if (!quantity) return ""
    return kind === "cpu" ? describeCpu(quantity.value) : describeMemory(quantity.value)
  }

  return (
    <fieldset data-slot="k8s-resource-input" className={cn("grid w-full max-w-md min-w-0 gap-3 text-sm", className)} {...props}>
      <legend className="mb-1.5 font-medium">{t.legend}</legend>
      <div className="grid grid-cols-2 gap-x-3 gap-y-3">
        {FIELDS.map(([kind, side]) => {
          const key: FieldKey = `${kind}.${side}`
          const Icon = kind === "cpu" ? Cpu : MemoryStick
          return (
            <div key={key} className="grid min-w-0 content-start gap-1.5">
              <label htmlFor={`${id}-${key}`} className="flex w-fit items-center gap-1.5 text-xs font-medium text-muted-foreground">
                <Icon aria-hidden className="size-3.5" />
                {t[key]}
              </label>
              <input
                ref={(element) => {
                  inputs.current[key] = element
                }}
                id={`${id}-${key}`}
                value={current[kind][side]}
                onChange={(event) => setField(key, event.target.value)}
                onPaste={(event) => {
                  const yaml = parseResourcesYaml(event.clipboardData.getData("text"))
                  if (!yaml) return
                  event.preventDefault()
                  update(yaml)
                  setPasted(true)
                }}
                placeholder={kind === "cpu" ? t.cpuPlaceholder : t.memoryPlaceholder}
                spellCheck={false}
                autoCapitalize="none"
                autoCorrect="off"
                aria-invalid={flagged.has(key) || undefined}
                aria-describedby={`${id}-${key}-read`}
                className="h-9 w-full min-w-0 rounded-md border bg-transparent px-3 font-mono text-base shadow-xs transition-[color,box-shadow] outline-none placeholder:text-muted-foreground/70 focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 aria-invalid:border-destructive md:text-sm dark:bg-input/30"
              />
              <span id={`${id}-${key}-read`} className="min-h-4 text-xs text-muted-foreground">
                {readback(kind, side)}
              </span>
            </div>
          )
        })}
      </div>
      <span role="status" className="sr-only">
        {announced}
      </span>
      {pasted && <p className="text-xs text-muted-foreground">{t.pasted}</p>}
      {summary && (
        <p className={cn("flex items-center gap-1.5 text-xs", errors ? "text-muted-foreground" : "text-emerald-700 dark:text-emerald-400")}>
          {errors ? <TriangleAlert aria-hidden className="size-3.5 text-red-600 dark:text-red-400" /> : <CircleCheck aria-hidden className="size-3.5" />}
          {summary}
        </p>
      )}
      {issues.length > 0 && (
        <ul ref={list} className="grid gap-1.5 text-xs">
          {issues.map((issue, index) => {
            const Icon = icons[issue.severity]
            return (
              <li key={`${issue.kind}-${issue.field}-${index}`} className={cn("flex gap-1.5", tones[issue.severity])}>
                <span className="flex h-6 shrink-0 items-center">
                  <Icon aria-hidden className="size-3.5" />
                </span>
                <span className="flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1">
                  <span className="py-1">{fill(t[issue.kind], { field: t[issue.field], ...issue.detail })}</span>
                  {issue.fixes.map((fix) => (
                    <button key={`${fix.action}-${fix.label}`} type="button" data-fix="" onClick={(event) => applyFix(issue, fix.set, event.currentTarget)} className={fixClass(issue.severity === "error")}>
                      {fix.action === "swap" ? t.swap : fill(fix.action === "use" ? t.use : t[fix.action], { value: fix.label })}
                    </button>
                  ))}
                </span>
              </li>
            )
          })}
        </ul>
      )}
      {anything && <p className="rounded-md border bg-muted/40 px-3 py-2 text-xs text-muted-foreground">{t[qos]}</p>}
    </fieldset>
  )
}
